      await pg.add_init_script('''(()=>{const seen=new Set();const out=t=>{t=(t||'').replace(/\\s+/g,' ').trim();if(t&&/[A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż]/.test(t)&&!seen.has(t)){seen.add(t);console.log('__S'+t)}};
        const walk=n=>{if(n.nodeType===3){if(!n.parentElement?.closest('script,style'))out(n.data);return}if(n.nodeType!==1)return;for(const a of ['placeholder','title','data-tip','aria-label'])if(n.hasAttribute?.(a))out(n.getAttribute(a));n.childNodes.forEach(walk)};
        new MutationObserver(ms=>ms.forEach(m=>{if(m.type==='characterData')out(m.target.data);else if(m.type==='attributes')out(m.target.getAttribute(m.attributeName));else m.addedNodes.forEach(walk)})).observe(document,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','data-tip','aria-label']});})()''')
